using System.Collections.Generic;
using System.IO;
using System.Linq;
using System.Text;
using UnityEditor;
using UnityEngine;

namespace DocMe.EyeInstaller
{
    /// <summary>Tracks which model file an install was built from, and turns stored picks back into vertices.</summary>
    public static class InstallSource
    {
        public const string GenDir = "Assets/DocMe Generated/EyeInstaller";

        /// <summary>The model file a mesh ultimately comes from. A mesh generated by the other tool
        /// inherits that tool's recorded source.</summary>
        public static void Root(GameObject avatar, Mesh mesh, out string path, out string meshName)
        {
            path = mesh != null ? AssetDatabase.GetAssetPath(mesh) : null;
            meshName = mesh != null ? mesh.name : null;
            if (string.IsNullOrEmpty(path) || !path.StartsWith(GenDir)) return;

            var eye = avatar.GetComponent<DocMeEyeInstall>();
            if (eye != null)
                foreach (var h in eye.hiddenRenderers)
                    if (h.modifiedMesh == mesh && !string.IsNullOrEmpty(h.sourcePath)) { path = h.sourcePath; meshName = h.sourceMeshName; return; }

            var hide = avatar.GetComponent<DocMeIslandHide>();
            if (hide != null)
                foreach (var e in hide.entries)
                    if (e.modifiedMesh == mesh && !string.IsNullOrEmpty(e.sourcePath)) { path = e.sourcePath; meshName = e.sourceMeshName; return; }
        }

        public static string Hash(IEnumerable<string> paths)
        {
            var sb = new StringBuilder();
            foreach (var p in paths.Where(p => !string.IsNullOrEmpty(p) && !p.StartsWith(GenDir)).Distinct().OrderBy(p => p))
                sb.Append(p).Append(':').Append(AssetDatabase.GetAssetDependencyHash(p)).Append(';');
            return sb.ToString();
        }

        /// <summary>The source mesh by name, for when the stored reference went missing.</summary>
        public static Mesh Resolve(string path, string meshName, string rendererName)
        {
            if (string.IsNullOrEmpty(path) || path.StartsWith(GenDir)) return null;
            var meshes = AssetDatabase.LoadAllAssetsAtPath(path).OfType<Mesh>().ToList();
            return meshes.FirstOrDefault(m => m.name == meshName) ?? meshes.FirstOrDefault(m => m.name == rendererName);
        }

        public static DocMePick ToPick(GameObject avatar, string label, EyeSeed seed)
        {
            Vector3 world = seed.point;
            if (world == default && seed.renderer != null)
            {
                var verts = EyeMeshUtil.BakeWorldVertices(seed.renderer, out var baked);
                Object.DestroyImmediate(baked);
                if (seed.vertex >= 0 && seed.vertex < verts.Length) world = verts[seed.vertex];
            }
            return new DocMePick { label = label, renderer = seed.renderer, avatarLocalPoint = avatar.transform.InverseTransformPoint(world) };
        }

        public class BakeCache
        {
            readonly Dictionary<SkinnedMeshRenderer, (Vector3[] world, int[] tris)> map = new Dictionary<SkinnedMeshRenderer, (Vector3[], int[])>();
            public (Vector3[] world, int[] tris) Get(SkinnedMeshRenderer r)
            {
                if (map.TryGetValue(r, out var v)) return v;
                var world = EyeMeshUtil.BakeWorldVertices(r, out var baked);
                Object.DestroyImmediate(baked);
                return map[r] = (world, r.sharedMesh.triangles);
            }
        }

        /// <summary>Resolves a stored pick to the triangle it was clicked on (closest surface, not closest
        /// vertex: a neighbouring island's vertex can be nearer than the clicked triangle's own corners).
        /// Fails if no surface is left near that spot.</summary>
        public static bool TryResolve(GameObject avatar, DocMePick pick, BakeCache cache, out EyeSeed seed)
        {
            seed = default;
            var r = pick.renderer;
            if (r == null || r.sharedMesh == null || !r.sharedMesh.isReadable) return false;
            var (world, tris) = cache.Get(r);

            Vector3 target = avatar.transform.TransformPoint(pick.avatarLocalPoint);
            float tol = 0.004f * Mathf.Max(Mathf.Abs(avatar.transform.lossyScale.y), 1e-3f);
            float bestSq = tol * tol; int bestTri = -1;
            for (int t = 0; t < tris.Length; t += 3)
            {
                Vector3 a = world[tris[t]], b = world[tris[t + 1]], c = world[tris[t + 2]];
                if ((a - b).sqrMagnitude < 1e-14f && (a - c).sqrMagnitude < 1e-14f) continue; // collapsed
                float d = (ClosestOnTriangle(target, a, b, c) - target).sqrMagnitude;
                if (d < bestSq) { bestSq = d; bestTri = t; }
            }
            if (bestTri < 0) return false;

            int best = tris[bestTri];
            for (int k = 1; k < 3; k++)
                if ((world[tris[bestTri + k]] - target).sqrMagnitude < (world[best] - target).sqrMagnitude) best = tris[bestTri + k];
            seed = new EyeSeed { renderer = r, vertex = best, point = target };
            return true;
        }

        // Ericson, Real-Time Collision Detection 5.1.5
        static Vector3 ClosestOnTriangle(Vector3 p, Vector3 a, Vector3 b, Vector3 c)
        {
            Vector3 ab = b - a, ac = c - a, ap = p - a;
            float d1 = Vector3.Dot(ab, ap), d2 = Vector3.Dot(ac, ap);
            if (d1 <= 0f && d2 <= 0f) return a;
            Vector3 bp = p - b;
            float d3 = Vector3.Dot(ab, bp), d4 = Vector3.Dot(ac, bp);
            if (d3 >= 0f && d4 <= d3) return b;
            float vc = d1 * d4 - d3 * d2;
            if (vc <= 0f && d1 >= 0f && d3 <= 0f) return a + ab * (d1 / (d1 - d3));
            Vector3 cp = p - c;
            float d5 = Vector3.Dot(ab, cp), d6 = Vector3.Dot(ac, cp);
            if (d6 >= 0f && d5 <= d6) return c;
            float vb = d5 * d2 - d1 * d6;
            if (vb <= 0f && d2 >= 0f && d6 <= 0f) return a + ac * (d2 / (d2 - d6));
            float va = d3 * d6 - d5 * d4;
            if (va <= 0f && (d4 - d3) >= 0f && (d5 - d6) >= 0f) return b + (c - b) * ((d4 - d3) / ((d4 - d3) + (d5 - d6)));
            float denom = 1f / (va + vb + vc);
            return a + ab * (vb * denom) + ac * (vc * denom);
        }
    }

    /// <summary>Hide Mesh Islands logic, separate from its window so it can be re-run after a reimport.</summary>
    public static class HideIslandsCore
    {
        const string HideShape = "DocMe_HideIslands";

        public static bool Apply(GameObject avatar, List<EyeSeed> picks, bool deleteGeometry, bool sinkIntoHead,
                                 out int verts, out int meshes, out int skippedNewEye)
        {
            verts = meshes = skippedNewEye = 0;
            if (avatar == null || picks == null) return false;
            if (avatar.GetComponent<DocMeIslandHide>() != null) Revert(avatar);

            Undo.RegisterFullObjectHierarchyUndo(avatar, "Hide Mesh Islands");
            if (!AssetDatabase.IsValidFolder(InstallSource.GenDir))
            {
                Directory.CreateDirectory(Path.Combine(Directory.GetCurrentDirectory(), InstallSource.GenDir));
                AssetDatabase.Refresh();
            }

            var perRenderer = new Dictionary<SkinnedMeshRenderer, List<List<int>>>();
            var newEye = new Dictionary<SkinnedMeshRenderer, HashSet<int>>();
            var used = new List<EyeSeed>();
            foreach (var p in picks)
            {
                if (p.renderer == null || p.renderer.sharedMesh == null || !p.renderer.sharedMesh.isReadable) continue;
                var island = EyeMeshHider.SelectIslandFromSeed(p.renderer, p.vertex, Vector3.zero, Vector3.forward, out _, out _);
                if (island.Count == 0) continue;

                if (!newEye.TryGetValue(p.renderer, out var canvas)) newEye[p.renderer] = canvas = NewEyeVerts(avatar, p.renderer);
                if (island.Exists(canvas.Contains)) { skippedNewEye++; continue; } // never hide the installed eye

                if (!perRenderer.TryGetValue(p.renderer, out var l)) perRenderer[p.renderer] = l = new List<List<int>>();
                l.Add(island);
                used.Add(p);
            }
            if (perRenderer.Count == 0) return false;

            var marker = Undo.AddComponent<DocMeIslandHide>(avatar);
            marker.deleteGeometry = deleteGeometry;
            marker.sinkIntoHead = sinkIntoHead;
            marker.appliedAt = System.DateTime.UtcNow.Ticks;
            foreach (var p in used) marker.picks.Add(InstallSource.ToPick(avatar, "", p));

            var anim = avatar.GetComponentInChildren<Animator>();
            var head = anim != null && anim.isHuman ? anim.GetBoneTransform(HumanBodyBones.Head) : null;

            foreach (var kv in perRenderer)
            {
                var smr = kv.Key;
                var src = smr.sharedMesh;
                var work = Object.Instantiate(src);
                work.name = src.name + (deleteGeometry ? "_DocMeTrimmed" : "_DocMeHidden");

                bool ok;
                if (deleteGeometry) ok = EyeMeshHider.RemoveIslandTriangles(work, kv.Value);
                else
                {
                    Vector3? sink = null;
                    if (sinkIntoHead && EyeMeshHider.TryGetBoneBindPosition(smr, head, out var hp)) sink = hp;
                    ok = EyeMeshHider.AddHideShape(work, kv.Value, HideShape, default, 2f, sink);
                }
                if (!ok) { Object.DestroyImmediate(work); continue; }

                AssetDatabase.CreateAsset(work, AssetDatabase.GenerateUniqueAssetPath(InstallSource.GenDir + "/" + work.name + ".asset"));

                var entry = new DocMeIslandHide.Entry
                {
                    renderer = smr, originalMesh = src, modifiedMesh = work,
                    blendShapeName = deleteGeometry ? null : HideShape,
                };
                InstallSource.Root(avatar, src, out entry.sourcePath, out entry.sourceMeshName);
                marker.entries.Add(entry);

                smr.sharedMesh = work;
                if (!deleteGeometry) smr.SetBlendShapeWeight(work.GetBlendShapeIndex(HideShape), 100f);
                foreach (var island in kv.Value) verts += island.Count;
                meshes++;
            }

            marker.sourceHash = InstallSource.Hash(marker.entries.Select(e => e.sourcePath));
            EditorUtility.SetDirty(avatar);
            AssetDatabase.SaveAssets();
            return meshes > 0;
        }

        static HashSet<int> NewEyeVerts(GameObject avatar, SkinnedMeshRenderer smr)
        {
            var set = new HashSet<int>();
            var eye = avatar.GetComponent<DocMeEyeInstall>();
            if (eye == null) return set;
            foreach (var h in eye.hiddenRenderers)
                if (h.reshaded && h.renderer == smr && h.modifiedMesh != null && smr.sharedMesh == h.modifiedMesh)
                    set.UnionWith(h.modifiedMesh.GetTriangles(h.modifiedMesh.subMeshCount - 1));
            return set;
        }

        public static void Revert(GameObject avatar)
        {
            var marker = avatar != null ? avatar.GetComponent<DocMeIslandHide>() : null;
            if (marker == null) return;

            Undo.RegisterFullObjectHierarchyUndo(avatar, "Revert Hide Mesh Islands");
            foreach (var e in marker.entries)
            {
                if (e.renderer != null)
                {
                    var restore = e.originalMesh != null ? e.originalMesh : InstallSource.Resolve(e.sourcePath, e.sourceMeshName, e.renderer.name);
                    if (restore != null) e.renderer.sharedMesh = restore;
                }
                if (e.modifiedMesh != null)
                {
                    string p = AssetDatabase.GetAssetPath(e.modifiedMesh);
                    if (!string.IsNullOrEmpty(p)) AssetDatabase.DeleteAsset(p);
                }
            }
            Undo.DestroyObjectImmediate(marker);
            EditorUtility.SetDirty(avatar);
            AssetDatabase.SaveAssets();
        }
    }

    /// <summary>Runs the stored installs again on the current source model (after a reimport).</summary>
    public static class DocMeReapply
    {
        const string AutoKey = "DocMe.EyeInstaller.autoReapply";
        public static bool AutoEnabled
        {
            get => EditorPrefs.GetBool(AutoKey, true);
            set => EditorPrefs.SetBool(AutoKey, value);
        }

        public static IEnumerable<string> SourcePaths(GameObject avatar)
        {
            var eye = avatar.GetComponent<DocMeEyeInstall>();
            if (eye != null) foreach (var h in eye.hiddenRenderers) yield return h.sourcePath;
            var hide = avatar.GetComponent<DocMeIslandHide>();
            if (hide != null) foreach (var e in hide.entries) yield return e.sourcePath;
        }

        /// <summary>True when the source model was reimported since the install.</summary>
        public static bool IsStale(GameObject avatar)
        {
            if (avatar == null) return false;
            var eye = avatar.GetComponent<DocMeEyeInstall>();
            var hide = avatar.GetComponent<DocMeIslandHide>();
            if (eye != null && !string.IsNullOrEmpty(eye.sourceHash) &&
                eye.sourceHash != InstallSource.Hash(eye.hiddenRenderers.Select(h => h.sourcePath))) return true;
            if (hide != null && !string.IsNullOrEmpty(hide.sourceHash) &&
                hide.sourceHash != InstallSource.Hash(hide.entries.Select(e => e.sourcePath))) return true;
            return false;
        }

        /// <summary>Hides the parts behind stored picks again on the current mesh.</summary>
        public static string ReapplyHide(GameObject avatar, List<DocMePick> picks, bool deleteGeometry, bool sinkIntoHead)
        {
            var cache = new InstallSource.BakeCache();
            var seeds = new List<EyeSeed>();
            int lost = 0;
            foreach (var p in picks)
                if (InstallSource.TryResolve(avatar, p, cache, out var seed)) seeds.Add(seed); else lost++;
            bool ok = HideIslandsCore.Apply(avatar, seeds, deleteGeometry, sinkIntoHead, out int verts, out int meshes, out int skipped);
            var sb = new StringBuilder();
            sb.AppendLine(ok ? $"Hidden parts re-applied ({verts} verts)." : "Hidden parts: nothing left to hide.");
            if (lost + skipped > 0) sb.AppendLine($"⚠ {lost + skipped} hide pick(s) no longer match the mesh and were dropped.");
            return sb.ToString().TrimEnd();
        }

        public static string ReapplyAll(GameObject avatar)
        {
            var sb = new StringBuilder();
            var eye = avatar.GetComponent<DocMeEyeInstall>();
            var hide = avatar.GetComponent<DocMeIslandHide>();
            if (eye == null && hide == null) return "Nothing installed.";
            if ((eye != null && eye.appliedAt == 0) || (hide != null && hide.appliedAt == 0))
                return "⚠ Installed with an older version that didn't record its settings. Revert and install once more; after that it re-applies by itself.";

            var eyeRecipe = eye != null ? eye.recipe : null;
            long eyeAt = eye != null ? eye.appliedAt : 0;
            var hidePicks = hide != null ? new List<DocMePick>(hide.picks) : null;
            bool hideDelete = hide != null && hide.deleteGeometry, hideSink = hide == null || hide.sinkIntoHead;
            long hideAt = hide != null ? hide.appliedAt : 0;

            HideIslandsCore.Revert(avatar);
            EyeInstallerCore.Revert(avatar);

            void Eyes()
            {
                if (eyeRecipe == null) return;
                var eyes = EyeAvatarDetector.Detect(avatar, out _);
                var cache = new InstallSource.BakeCache();
                int lost = 0;
                foreach (var p in eyeRecipe.picks)
                {
                    var d = eyes.Find(x => x.label == p.label);
                    if (d != null && InstallSource.TryResolve(avatar, p, cache, out var seed)) d.seeds.Add(seed);
                    else lost++;
                }
                EyeInstallerCore.Install(avatar, eyes, EyeInstallerCore.FromRecipe(eyeRecipe));
                sb.AppendLine(avatar.GetComponent<DocMeEyeInstall>() != null ? "Eyes re-applied." : "⚠ Eyes could not be re-applied.");
                if (lost > 0) sb.AppendLine($"⚠ {lost} eye pick(s) no longer match the mesh and were dropped (auto detection used where none were left).");
            }

            void Hide()
            {
                if (hidePicks == null || hidePicks.Count == 0) return;
                sb.AppendLine(ReapplyHide(avatar, hidePicks, hideDelete, hideSink));
            }

            if (hideAt != 0 && hideAt < eyeAt) { Hide(); Eyes(); } else { Eyes(); Hide(); }
            return sb.ToString().TrimEnd();
        }
    }

    class ReimportWatcher : AssetPostprocessor
    {
        static void OnPostprocessAllAssets(string[] imported, string[] deleted, string[] moved, string[] movedFrom)
        {
            if (!DocMeReapply.AutoEnabled || EditorApplication.isPlayingOrWillChangePlaymode) return;
            var changed = new HashSet<string>(imported.Where(p => !p.StartsWith(InstallSource.GenDir)));
            if (changed.Count == 0) return;

            var avatars = new HashSet<GameObject>();
            foreach (var m in Object.FindObjectsOfType<DocMeEyeInstall>(true)) avatars.Add(m.gameObject);
            foreach (var m in Object.FindObjectsOfType<DocMeIslandHide>(true)) avatars.Add(m.gameObject);
            var hit = avatars.Where(a => DocMeReapply.SourcePaths(a).Any(p => p != null && changed.Contains(p))).ToList();
            if (hit.Count == 0) return;

            EditorApplication.delayCall += () =>
            {
                foreach (var a in hit)
                    if (a != null) Debug.Log($"[DocMe Eyes] '{a.name}': source model reimported.\n" + DocMeReapply.ReapplyAll(a), a);
            };
        }
    }
}
